    if (!editForm.label.trim() || !editForm.question.trim() || !editForm.answer.trim()) {
      t && t("يرجى ملء كافة الحقول", "error");
      return;
    }
    const next = inqs.map(item => item.id === id ? { ...item, label: editForm.label.trim(), question: editForm.question.trim(), answer: editForm.answer.trim() } : item);
